CREATE EXTENSION vector;
ALTER TABLE notes ADD COLUMN embedding vector(768);
SELECT id, title FROM notes
WHERE author = '서윤'
ORDER BY embedding <=> $1
LIMIT 5;

CREATE INDEX ON notes USING hnsw (embedding vector_cosine_ops)
  WITH (m = 16, ef_construction = 64);
SET hnsw.ef_search = 100;

CREATE INDEX ON notes USING hnsw
  ((binary_quantize(embedding)::bit(768)) bit_hamming_ops);
SELECT id FROM (
  SELECT id, embedding FROM notes
  ORDER BY binary_quantize(embedding)::bit(768) <~> binary_quantize($1) LIMIT 100
) t ORDER BY embedding <=> $1 LIMIT 10;
